import { createHash } from "node:crypto";
import { isPubliclyReadable } from "./policy.mjs";
import { invalidAuthorizationHeader, missingAuthorization, notFound } from "./problems.mjs";

// The authorization decision for a Space endpoint, made from what the
// gateway authorizer established (it verifies the capability invocation
// and answers with the result in the request context; it never denies,
// because a gateway denial is always a 403 and the spec's answers are
// different):
//
//   - a verified invocation proceeds (subject to the container rule and the
//     Digest check);
//   - an invocation that did not verify, or an unsigned request to
//     something no PublicCanRead policy covers, is answered as the spec
//     requires: 404 for what the caller may not see, 200 with no items for
//     a listing, 401 for an unsigned write.
//
// The endpoint functions call this through handler(); the operation then
// finds `route.invoker` (the verified DID), `route.public`, and for a
// listing `route.authorized`.

const isRead = (req) => req.method === "GET" || req.method === "HEAD";

export async function authorize(req, route, { listing = false, rootOnly = false, readable = true } = {}) {
  const auth = req.auth;
  if (auth.space === "missing") {
    throw notFound();
  }

  if (auth.signed === "true") {
    if (auth.verified !== "true") {
      if (listing && isRead(req)) {
        route.authorized = false;
        return;
      }
      throw notFound();
    }
    if (rootOnly && auth.delegated === "true") {
      throw notFound();
    }
    verifyDigest(req);
    route.invoker = auth.controller;
    route.authorized = true;
    return;
  }

  if (isRead(req) && readable) {
    if (await isPubliclyReadable(route.spaceId, route)) {
      route.public = true;
      route.authorized = true;
      return;
    }
    if (listing) {
      route.authorized = false;
      return;
    }
    throw notFound();
  }
  if (isRead(req)) {
    throw notFound();
  }
  throw missingAuthorization();
}

// The spec's request-body integrity rule: a request with a body carries a
// Digest header (multihash form, `mh=uEi...`) that the signature covers, and
// the server recomputes it over the bytes it received. The authorizer only
// sees headers, so this is where the signature gets bound to the body.
export function verifyDigest(req) {
  if (req.body === null) {
    return;
  }
  const header = req.headers.digest;
  if (!header) {
    throw invalidAuthorizationHeader("A request with a body must carry a Digest header.");
  }
  const [key, value] = header.split(/=(.+)/);
  const sha256 = createHash("sha256").update(req.body).digest();
  let expected;
  if (key === "mh") {
    expected = "u" + Buffer.concat([Buffer.from([0x12, 0x20]), sha256]).toString("base64url");
  } else if (key.toUpperCase() === "SHA-256") {
    expected = sha256.toString("base64");
  } else {
    throw invalidAuthorizationHeader(`Unsupported Digest algorithm "${key}".`);
  }
  if (value !== expected) {
    throw invalidAuthorizationHeader("The Digest header does not match the request body.");
  }
}
